          explanation: 'One of the most powerful passages in the Devi Mahatmyam. When the Mother\'s gentleness is met with cruelty, she does not become weak. From her own furrowed brow — from her concentrated awareness — Kali emerges. Kali is not "another goddess" but the Mother\'s own fierce face. The lesson: love itself, when threatened, has a fierce mode. The compassion that allows everything is not the same as the compassion that ALLOWS injustice. Real compassion has teeth.',
          keywords: [],
